fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    if n <= 1 {
        // If empty or only one element, return as is
        return numbers;
    }

    // create a vector with capacity 2*n - 1
    let mut result = Vec::with_capacity(2 * n - 1);

    for i in 0..n {
        // push the original number
        result.push(numbers[i]);

        // If this is not the last element, push the delimiter
        if i != n - 1 {
            result.push(delimiter);
        }
    }

    result
}